#include <WiFi.h>
#include <Adafruit_SSD1306.h>
#include <Adafruit_GFX.h>
#include <Wire.h>




void setup() {
  Serial.begin(115200);
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
  delay(100);
  Serial.println("Wi-Fi scan started");
}

void loop() {
  int count = WiFi.scanNetworks();
  Serial.printf("Found %d network(s)\n", count);

  for (int i = 0; i < count; i++) {
    Serial.printf("%2d: %s (%d dBm)%s\n",
      i + 1,
      WiFi.SSID(i).c_str(),
      WiFi.RSSI(i),
      WiFi.encryptionType(i) == WIFI_AUTH_OPEN ? " open" : "");
  }

  WiFi.scanDelete();
  delay(5000);
}
